function hexToRgb(hex){hex = hex.replace(/^#/, "");if (hex.length === 3) hex = [...hex].map((c) => c + c).join("");if (!/^[0-9a-fA-F]{6}$/.test(hex)) return null;const num = parseInt(hex, 16);return{r: (num >> 16) & 255, g: (num >> 8) & 255, b: num & 255};}function rgbToHsl(r, g, b){r /= 255;g /= 255;b /= 255;const max = Math.max(r, g, b), min = Math.min(r, g, b);let h, s, l = (max + min) / 2;if (max === min){h = s = 0;}else{const d = max - min;s = l > 0.5 ? d / (2 - max - min) : d / (max + min);switch (max){case r: h = (g - b) / d + (g < b ? 6 : 0);break;case g: h = (b - r) / d + 2;break;case b: h = (r - g) / d + 4;break;}h /= 6;}return{h: Math.round(h * 360), s: Math.round(s * 100), l: Math.round(l * 100)};}function parseColor(input){input = input.trim();let rgb = null;if (input.startsWith("#") || /^[0-9a-fA-F]{3,6}$/.test(input)){rgb = hexToRgb(input);}else{const m = input.match(/(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);if (m) rgb ={r: +m[1], g: +m[2], b: +m[3]};}return rgb;}function formatOutputs(rgb){const hex = "#" + [rgb.r, rgb.g, rgb.b].map((v) => v.toString(16).padStart(2, "0")).join("");const floats = [rgb.r, rgb.g, rgb.b].map((v) => (v / 255).toFixed(4));const hsl = rgbToHsl(rgb.r, rgb.g, rgb.b);return{"HEX": hex, "RGB (integer)": `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`, "RGB (float 0-1, for OpenGL/shaders)": `(${floats[0]}f, ${floats[1]}f, ${floats[2]}f)`, "HSL": `hsl(${hsl.h}, ${hsl.s}%, ${hsl.l}%)`};}function executeColorConvert(){const raw = document.getElementById("color-input").value;const swatch = document.getElementById("color-swatch");const out = document.getElementById("color-result");const rgb = parseColor(raw);if (!rgb || [rgb.r, rgb.g, rgb.b].some((v) => v < 0 || v > 255 || isNaN(v))){GAMA.say(raw ? "error" : "idle");out.textContent = raw ? "// unreadable color - use #hex or r,g,b" : "";swatch.style.background = "transparent";return;}const outputs = formatOutputs(rgb);swatch.style.background = outputs["HEX"];out.innerHTML = Object.entries(outputs).map(([label, val]) => `<div><span style="color:var(--phosphor-dim)">${label}:</span> ${val}</div>` ).join("");GAMA.say("success");}